        "avatar": "https://media.licdn.com/dms/image/v2/D4E03AQEKQZAk0wEgEg/profile-displayphoto-scale_400_400/B4EZ5Bbr0ZHcAg-/0/1779214238104?e=1784764800&v=beta&t=uU4IBQm-YaDhRZwOLadS5dyBRdUJpSePMdp01yNfMQc"
